package io.github.byshadow64.tgproxy.core

import org.junit.Assert.*
import org.junit.Test
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.Base64
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

class HelperPairingClientTest {
    // Public synthetic interoperability vector generated by Desktop Dev/helper_pairing.py, never live credentials.
    private val code = "TG1.AAECAwQFBgc.EBESExQVFhcYGRobHB0eHw"
    private val id = "AAECAwQFBgc"
    private val key = hex("3bec55e7ba0c1d9f58f3db0e34195c62a64e0c812212d28067739a392d0c3a0e")
    private val clientNonce = ByteArray(32) { it.toByte() }
    private val serverNonce = ByteArray(32) { (it + 32).toByte() }
    private val vectorCert = ByteArray(32) { (it + 64).toByte() }
    private val token = "synthetic-vector-token-not-a-real-credential-123456"
    private val vectorPayload = "{\"v\":1,\"port\":8444,\"fingerprint\":\"404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f\",\"token\":\"$token\"}"

    @Test fun matchesIndependentPythonPairingV1ProofAndResponseVector() {
        val parsed = HelperPairingClient.parseCode(code)
        assertEquals(id, parsed.first); assertArrayEquals(key, parsed.second)
        assertArrayEquals(hex("eb764274e12a58d5840965e9f590c912fcfd8a2840b73467c137ddc34e75f4c5"), HelperPairingClient.clientProof(key, id, clientNonce, vectorCert))
        val proof = hex("1eb8fd1df0b1f3936341e6ea506e1d8e0ae09958dedf73bc95efa787bebaff83")
        val response = envelope(vectorPayload.toByteArray(), proof)
        val paired = HelperPairingClient.verifyResponse(response, id, key, clientNonce, vectorCert, PairingEndpoint("127.0.0.1", 9444))
        assertEquals(token, paired.token)
        assertEquals(9444, paired.port) // Preserve the reachable public/NAT port, not an internal advertised port.
        assertEquals("127.0.0.1", paired.host)
        assertFalse(paired.toString().contains(token)); assertFalse(PairingEndpoint("private-host", 9444).toString().contains("private-host"))
    }

    @Test fun codeAndBase64UrlRequireCanonicalUnusedBitsAndRejectPadding() {
        for (invalid in listOf(code.replace("FBgc.", "FBgd."), code.replace("eHw", "eHx"), "$code=", code.lowercase(), "TG1.bad.bad")) {
            try { HelperPairingClient.parseCode(invalid); fail() } catch (failure: PairingException) { assertEquals(PairingFailureCode.INVALID_CODE, failure.code) }
        }
        assertArrayEquals(byteArrayOf(102), HelperPairingClient.decode("Zg"))
        for (invalid in listOf("Zh", "Zg=", "Zg==", "+/", "", "Z g")) {
            try { HelperPairingClient.decode(invalid); fail() } catch (_: IllegalArgumentException) {}
        }
    }

    @Test fun flatJsonRejectsAmbiguityInvalidUtf8AndNonJsonUnicodeEscapes() {
        val invalid = listOf(
            "{\"v\":1,\"v\":1}", "{\"v\":1,\"\\u0076\":1}", "{\"v\":01}", "{\"v\":-1}", "{\"v\":+1}", "{\"v\":1.0}",
            "{\"v\":null}", "{\"v\":true}", "{\"v\":{}}", "{\"v\":[]}", "{\"v\":1,}", "{\"v\":1} trailing",
            "{\"v\":\"\\u+123\"}", "{\"v\":\"\\u-123\"}", "{\"v\":\"\\u123z\"}", "{\"v\":2147483648}",
        )
        for (text in invalid) { try { PairingJson.parse(text.toByteArray(), 4096); fail(text) } catch (_: Exception) {} }
        try { PairingJson.parse(byteArrayOf('{'.code.toByte(), '"'.code.toByte(), 0xc0.toByte(), 0xaf.toByte()), 4096); fail() } catch (_: Exception) {}
        assertEquals(mapOf("v" to "A"), PairingJson.parse("{\"v\":\"\\u0041\"}".toByteArray(), 4096))
    }

    @Test fun numericEndpointParsingNeverAcceptsUrlHostnameOrNumericShorthand() {
        assertEquals("127.0.0.1", HelperPairingClient.endpoint("127.0.0.1:9444").host)
        assertEquals(9444, HelperPairingClient.endpoint("127.0.0.1:9444").port)
        assertEquals(8444, HelperPairingClient.endpoint("[::1]").port)
        for (invalid in listOf("helper.example", "https://127.0.0.1", "127.1", "256.0.0.1", "127.0.0.1:0", "127.0.0.1:65536", "[::1]evil", "127.0.0.1/path")) {
            try { HelperPairingClient.endpoint(invalid); fail() } catch (failure: PairingException) { assertEquals(PairingFailureCode.INVALID_ADDRESS, failure.code) }
        }
    }

    @Test fun authenticatedResponseRejectsNonceCertificatePayloadAndFingerprintSubstitution() {
        val validProof = hex("1eb8fd1df0b1f3936341e6ea506e1d8e0ae09958dedf73bc95efa787bebaff83")
        val valid = envelope(vectorPayload.toByteArray(), validProof)
        val endpoint = PairingEndpoint("127.0.0.1", 8444)
        val cases = listOf(
            { HelperPairingClient.verifyResponse(valid, id, key, clientNonce.copyOf().also { it[0] = 99 }, vectorCert, endpoint) },
            { HelperPairingClient.verifyResponse(valid, id, key, clientNonce, vectorCert.copyOf().also { it[0] = 99 }, endpoint) },
            { HelperPairingClient.verifyResponse(envelope(vectorPayload.replace("123456", "654321").toByteArray(), validProof), id, key, clientNonce, vectorCert, endpoint) },
        )
        for (call in cases) { try { call(); fail() } catch (_: IllegalArgumentException) {} }
        val badFingerprint = vectorPayload.replace("40414243", "00000000").toByteArray()
        val signedBad = serverProof(clientNonce, vectorCert, badFingerprint)
        try { HelperPairingClient.verifyResponse(envelope(badFingerprint, signedBad), id, key, clientNonce, vectorCert, endpoint); fail() } catch (_: IllegalArgumentException) {}
    }

    @Test fun localTlsEnrollmentAuthenticatesExactCertificateAndSendsNoCodeOrBearerToken() {
        val clientWire = AtomicReference<String>()
        TlsFixture.server { socket ->
            val request = readRequest(socket)
            clientWire.set(request.second)
            val response = response(request.first, hex(TlsFixture.pin))
            writeHelper(socket, response)
        }.use { server ->
            val paired = HelperPairingClient.pair("127.0.0.1:${server.port}", code)
            assertEquals(token, paired.token); assertEquals(TlsFixture.pin, paired.fingerprintHex); assertEquals(server.port, paired.port)
            server.assertSuccess()
        }
        val wire = clientWire.get()
        assertFalse(wire.contains(code)); assertFalse(wire.contains(code.substringAfterLast('.'))); assertFalse(wire.contains(token))
        assertTrue(wire.contains(id))
    }

    @Test fun localTlsDenialTamperingAndCertificateForwardingFailClosed() {
        for (mode in listOf("denied", "tampered", "substitution")) {
            TlsFixture.server { socket ->
                val request = readRequest(socket).first
                val reply = when (mode) {
                    "denied" -> "PAIR_NO".toByteArray()
                    "substitution" -> {
                        // A forwarder with a different certificate cannot reuse this observed client proof against the owner's server.
                        val nonce = Base64.getUrlDecoder().decode(request["nonce"] as String)
                        assertFalse(MessageDigest.isEqual(Base64.getUrlDecoder().decode(request["proof"] as String), clientProof(nonce, vectorCert)))
                        response(request, vectorCert)
                    }
                    else -> response(request, hex(TlsFixture.pin)).copyOf().also { it[it.size - 3] = if (it[it.size - 3] == 'A'.code.toByte()) 'B'.code.toByte() else 'A'.code.toByte() }
                }
                writeHelper(socket, reply)
            }.use { server ->
                try { HelperPairingClient.pair("127.0.0.1:${server.port}", code); fail(mode) }
                catch (failure: PairingException) { assertEquals(PairingFailureCode.UNVERIFIED_SERVER, failure.code); assertNull(failure.cause); assertFalse(failure.message!!.contains(code)) }
                server.assertSuccess()
            }
        }
    }

    @Test fun slowResponseAndCancellationCloseTlsSocketWithinDeadline() {
        for (cancel in listOf(false, true)) {
            val ready = CountDownLatch(1)
            val cancelled = AtomicBoolean(false)
            val outcome = AtomicReference<PairingFailureCode?>()
            val done = CountDownLatch(1)
            TlsFixture.server { socket ->
                readRequest(socket); ready.countDown()
                try { while (socket.getInputStream().read() >= 0) {} } catch (_: java.net.SocketException) {}
            }.use { server ->
                val began = System.nanoTime()
                Thread {
                    try { HelperPairingClient.pair("127.0.0.1:${server.port}", code, if (cancel) 2_000 else 500) { cancelled.get() } }
                    catch (failure: PairingException) { outcome.set(failure.code) }
                    finally { done.countDown() }
                }.apply { isDaemon = true; start() }
                assertTrue(ready.await(2, TimeUnit.SECONDS))
                if (cancel) cancelled.set(true)
                assertTrue(done.await(2, TimeUnit.SECONDS))
                assertEquals(if (cancel) PairingFailureCode.CANCELLED else PairingFailureCode.TIMEOUT, outcome.get())
                assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - began) < 2_000)
                server.assertSuccess()
            }
        }
    }

    private fun readRequest(socket: java.net.Socket): Pair<Map<String, Any>, String> {
        assertEquals("TGPAIR1", readHelper(socket).toString(StandardCharsets.US_ASCII))
        val bytes = readHelper(socket); assertTrue(bytes.size <= 1024)
        val request = PairingJson.parse(bytes, 1024)
        assertEquals(setOf("v", "id", "nonce", "proof"), request.keys); assertEquals(1, request["v"]); assertEquals(id, request["id"])
        val nonce = Base64.getUrlDecoder().decode(request["nonce"] as String)
        assertArrayEquals(clientProof(nonce, hex(TlsFixture.pin)), Base64.getUrlDecoder().decode(request["proof"] as String))
        return request to bytes.toString(StandardCharsets.US_ASCII)
    }

    private fun response(request: Map<String, Any>, cert: ByteArray): ByteArray {
        val fingerprint = cert.joinToString("") { "%02x".format(it.toInt() and 255) }
        val payload = "{\"v\":1,\"port\":8444,\"fingerprint\":\"$fingerprint\",\"token\":\"$token\"}".toByteArray()
        return envelope(payload, serverProof(Base64.getUrlDecoder().decode(request["nonce"] as String), cert, payload))
    }
    private fun envelope(payload: ByteArray, proof: ByteArray) = "{\"v\":1,\"nonce\":\"${b64(serverNonce)}\",\"payload\":\"${b64(payload)}\",\"proof\":\"${b64(proof)}\"}".toByteArray()
    private fun clientProof(nonce: ByteArray, cert: ByteArray) = mac("TGPROXY_PAIR_CLIENT_V1\u0000".toByteArray(), id.toByteArray(), byteArrayOf(0), nonce, cert)
    private fun serverProof(nonce: ByteArray, cert: ByteArray, payload: ByteArray) = mac("TGPROXY_PAIR_SERVER_V1\u0000".toByteArray(), id.toByteArray(), byteArrayOf(0), nonce, serverNonce, cert, payload)
    private fun mac(vararg parts: ByteArray): ByteArray = Mac.getInstance("HmacSHA256").run { init(SecretKeySpec(key, "HmacSHA256")); parts.forEach(::update); doFinal() }
    private fun b64(bytes: ByteArray) = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
}
